import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BTjPRYTP.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),r={name:"guide/troubleshooting.md"};function s(n,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Common issues and their solutions when running TeslaSync.</p><h2 id="connection-issues" tabindex="-1">Connection Issues <a class="header-anchor" href="#connection-issues" aria-label="Permalink to &quot;Connection Issues&quot;">​</a></h2><h3 id="backend-not-reachable" tabindex="-1">Backend Not Reachable <a class="header-anchor" href="#backend-not-reachable" aria-label="Permalink to &quot;Backend Not Reachable&quot;">​</a></h3><p><strong>Symptom:</strong> Frontend shows &quot;Unable to reach the server&quot; or connection timeout errors.</p><p><strong>Solutions:</strong></p><ol><li>Verify the backend is running: <code>docker compose ps</code></li><li>Check backend logs: <code>docker compose logs teslasync</code></li><li>Ensure port 8080 is not blocked by a firewall</li><li>Verify the <code>TESLASYNC_PORT</code> environment variable matches the frontend proxy config</li></ol><h3 id="tesla-api-authentication-failure" tabindex="-1">Tesla API Authentication Failure <a class="header-anchor" href="#tesla-api-authentication-failure" aria-label="Permalink to &quot;Tesla API Authentication Failure&quot;">​</a></h3><p><strong>Symptom:</strong> &quot;Failed to authenticate&quot; error when connecting Tesla account.</p><p><strong>Solutions:</strong></p><ol><li>Verify <code>TESLA_CLIENT_ID</code> and <code>TESLA_CLIENT_SECRET</code> in <code>.env</code></li><li>Ensure <code>TESLA_REDIRECT_URI</code> matches the registered callback URL in the Tesla Developer portal</li><li>Check if your Tesla API tokens have expired — try the &quot;Refresh&quot; button in Settings</li><li>Tesla&#39;s API may be temporarily down — check <a href="https://developer.tesla.com" target="_blank" rel="noreferrer">Tesla API status</a></li></ol><h3 id="database-connection-failure" tabindex="-1">Database Connection Failure <a class="header-anchor" href="#database-connection-failure" aria-label="Permalink to &quot;Database Connection Failure&quot;">​</a></h3><p><strong>Symptom:</strong> Backend starts but logs show &quot;failed to connect to database&quot;.</p><p><strong>Solutions:</strong></p><ol><li>Ensure PostgreSQL is running: <code>docker compose ps postgres</code></li><li>Check PostgreSQL logs: <code>docker compose logs postgres</code></li><li>Verify credentials: <code>POSTGRES_USER</code>, <code>POSTGRES_PASSWORD</code>, <code>POSTGRES_DB</code> in <code>.env</code></li><li>For external databases, verify <code>POSTGRES_HOST</code> and <code>POSTGRES_PORT</code></li><li>Check PostgreSQL is accepting connections: <code>docker compose exec postgres psql -U teslasync -c &quot;SELECT version();&quot;</code></li></ol><h2 id="performance-issues" tabindex="-1">Performance Issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to &quot;Performance Issues&quot;">​</a></h2><h3 id="high-memory-usage" tabindex="-1">High Memory Usage <a class="header-anchor" href="#high-memory-usage" aria-label="Permalink to &quot;High Memory Usage&quot;">​</a></h3><p><strong>Symptom:</strong> Backend memory grows over time.</p><p><strong>Solutions:</strong></p><ol><li>Reduce <code>POSITION_RETENTION_DAYS</code> (default 90) to keep fewer GPS points</li><li>Lower <code>POLL_INTERVAL</code> to reduce data collection frequency</li><li>Check for connection pool leaks in logs</li><li>Docker resource limits are set in <code>docker-compose.yml</code> — increase if needed</li></ol><h3 id="slow-dashboard-loading" tabindex="-1">Slow Dashboard Loading <a class="header-anchor" href="#slow-dashboard-loading" aria-label="Permalink to &quot;Slow Dashboard Loading&quot;">​</a></h3><p><strong>Symptom:</strong> Pages take several seconds to load.</p><p><strong>Solutions:</strong></p><ol><li>Enable Redis caching — ensure Redis is running: <code>docker compose ps redis</code></li><li>Reduce the default date range for analytics queries</li><li>Add database indexes for frequently queried columns (check migration files)</li><li>Consider adding indexes for frequently queried columns (check migration files)</li></ol><h3 id="port-conflicts-windows" tabindex="-1">Port Conflicts (Windows) <a class="header-anchor" href="#port-conflicts-windows" aria-label="Permalink to &quot;Port Conflicts (Windows)&quot;">​</a></h3><p><strong>Symptom:</strong> Docker containers fail to start with &quot;port already in use&quot; errors.</p><p><strong>Solutions:</strong></p><ol><li>Check for Hyper-V port exclusions: <code>netsh interface ipv4 show excludedportrange protocol=tcp</code></li><li>Change conflicting ports in <code>docker-compose.yml</code></li><li>Stop other services using the same ports</li></ol><h2 id="data-issues" tabindex="-1">Data Issues <a class="header-anchor" href="#data-issues" aria-label="Permalink to &quot;Data Issues&quot;">​</a></h2><h3 id="missing-vehicle-data" tabindex="-1">Missing Vehicle Data <a class="header-anchor" href="#missing-vehicle-data" aria-label="Permalink to &quot;Missing Vehicle Data&quot;">​</a></h3><p><strong>Symptom:</strong> Vehicle appears in the list but shows no data.</p><p><strong>Solutions:</strong></p><ol><li>Check if the vehicle is asleep — use the &quot;Wake&quot; button on the Commands page</li><li>Verify the polling worker is running: check backend logs for &quot;polling vehicle&quot; messages</li><li>The first poll after connecting takes ~30 seconds to populate data</li><li>Some data (drives, charges) requires the vehicle to actually drive or charge before appearing</li></ol><h3 id="vampire-drain-not-detected" tabindex="-1">Vampire Drain Not Detected <a class="header-anchor" href="#vampire-drain-not-detected" aria-label="Permalink to &quot;Vampire Drain Not Detected&quot;">​</a></h3><p><strong>Symptom:</strong> No vampire drain events appear.</p><p><strong>Solutions:</strong></p><ol><li>Vampire drain detection requires the vehicle to be parked for at least 1 hour</li><li>Ensure the poller is running during overnight parking periods</li><li>Check <code>WORKER_SLEEP_POLL_MULT</code> — a high value means less frequent sleeping-vehicle polls</li></ol><h3 id="incorrect-charging-costs" tabindex="-1">Incorrect Charging Costs <a class="header-anchor" href="#incorrect-charging-costs" aria-label="Permalink to &quot;Incorrect Charging Costs&quot;">​</a></h3><p><strong>Symptom:</strong> Charging costs show $0 or incorrect values.</p><p><strong>Solutions:</strong></p><ol><li>Set the base cost per kWh in Settings</li><li>For location-based pricing, create a geofence around your charger and set <code>cost_per_kwh</code></li><li>Supercharger costs are estimated — actual costs may vary</li></ol><h2 id="notification-issues" tabindex="-1">Notification Issues <a class="header-anchor" href="#notification-issues" aria-label="Permalink to &quot;Notification Issues&quot;">​</a></h2><h3 id="notifications-not-sending" tabindex="-1">Notifications Not Sending <a class="header-anchor" href="#notifications-not-sending" aria-label="Permalink to &quot;Notifications Not Sending&quot;">​</a></h3><p><strong>Symptom:</strong> Alert rules trigger but no notifications arrive.</p><p><strong>Solutions:</strong></p><ol><li>Verify the notification channel is enabled (toggle on the Notifications page)</li><li>Test the channel using the &quot;Test&quot; button</li><li>Check notification logs on the Notifications page for error details</li><li>For webhooks: verify the URL is reachable from the Docker network</li><li>For Discord/Slack: ensure the webhook URL is still valid (they can expire)</li></ol><h3 id="duplicate-notifications" tabindex="-1">Duplicate Notifications <a class="header-anchor" href="#duplicate-notifications" aria-label="Permalink to &quot;Duplicate Notifications&quot;">​</a></h3><p><strong>Symptom:</strong> Receiving the same notification multiple times.</p><p><strong>Solutions:</strong></p><ol><li>Check if multiple alert rules overlap (e.g., two rules for low battery at different thresholds)</li><li>Verify <code>POLL_INTERVAL</code> — very frequent polling can trigger alerts repeatedly</li><li>Alert rules have a built-in cooldown period — if you see rapid duplicates, report it as a bug</li></ol><h2 id="docker-issues" tabindex="-1">Docker Issues <a class="header-anchor" href="#docker-issues" aria-label="Permalink to &quot;Docker Issues&quot;">​</a></h2><h3 id="container-keeps-restarting" tabindex="-1">Container Keeps Restarting <a class="header-anchor" href="#container-keeps-restarting" aria-label="Permalink to &quot;Container Keeps Restarting&quot;">​</a></h3><p><strong>Symptom:</strong> <code>docker compose ps</code> shows a container restarting.</p><p><strong>Solutions:</strong></p><ol><li>Check container logs: <code>docker compose logs &lt;service-name&gt;</code></li><li>Verify environment variables are set correctly in <code>.env</code></li><li>For PostgreSQL: ensure the data volume is not corrupted — try <code>docker compose down -v</code> and re-create (⚠️ deletes data)</li><li>Check resource limits in <code>docker-compose.yml</code> — containers may be OOM-killed</li></ol><h3 id="docker-build-fails" tabindex="-1">Docker Build Fails <a class="header-anchor" href="#docker-build-fails" aria-label="Permalink to &quot;Docker Build Fails&quot;">​</a></h3><p><strong>Symptom:</strong> <code>docker compose build</code> fails.</p><p><strong>Solutions:</strong></p><ol><li>Ensure Docker Desktop has sufficient resources (4+ GB RAM)</li><li>Clear Docker build cache: <code>docker builder prune</code></li><li>Check if Go module downloads are failing (network/proxy issues)</li><li>For frontend builds: ensure <code>node_modules</code> is in <code>.dockerignore</code></li></ol><h2 id="grafana-issues" tabindex="-1">Grafana Issues <a class="header-anchor" href="#grafana-issues" aria-label="Permalink to &quot;Grafana Issues&quot;">​</a></h2><h3 id="dashboards-show-no-data" tabindex="-1">Dashboards Show &quot;No Data&quot; <a class="header-anchor" href="#dashboards-show-no-data" aria-label="Permalink to &quot;Dashboards Show &quot;No Data&quot;&quot;">​</a></h3><p><strong>Symptom:</strong> Grafana panels show &quot;No data&quot; even though the app has data.</p><p><strong>Solutions:</strong></p><ol><li>Verify the PostgreSQL datasource is configured: Grafana → Connections → Data Sources</li><li>Check datasource credentials match <code>POSTGRES_USER</code> / <code>POSTGRES_PASSWORD</code></li><li>Adjust the time range in Grafana (top-right corner) — default may be too narrow</li><li>The datasource should connect to <code>postgres:5432</code> (Docker internal hostname), not <code>localhost</code></li></ol><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><p>If your issue isn&#39;t covered here:</p><ol><li>Check the <a href="https://github.com/ev-dev-labs/TeslaSync/issues" target="_blank" rel="noreferrer">GitHub Issues</a> for known bugs</li><li>Search the backend logs: <code>docker compose logs teslasync | grep -i error</code></li><li>Open a new issue with: <ul><li>TeslaSync version / commit hash</li><li>Docker Compose output (<code>docker compose ps</code>)</li><li>Relevant log output</li><li>Steps to reproduce</li></ul></li></ol>',67)])])}const g=o(r,[["render",s]]);export{p as __pageData,g as default};
